function toggleFaq(e: MouseEvent<HTMLButtonElement>) {
  const btn = e.currentTarget;
  const content = btn.nextElementSibling as HTMLElement | null;
  const icon = btn.querySelector(".material-symbols-outlined") as HTMLElement | null;
  if (!content) return;
  const isHidden = content.classList.contains("hidden");
  document.querySelectorAll("#faq-container .font-body-md").forEach((el) => el.classList.add("hidden"));
  document.querySelectorAll<HTMLElement>("#faq-container .material-symbols-outlined").forEach((i) => (i.style.transform = "rotate(0deg)"));
  if (isHidden) { content.classList.remove("hidden"); if (icon) icon.style.transform = "rotate(180deg)"; }
}

